--- a/runtime/streaming/control_frame.go
+++ b/runtime/streaming/control_frame.go
@@ -12,6 +12,22 @@
 func EmitControlFrame(w io.Writer, ctrl ControlMessage) error {
+    // control frames are JSON with a fixed envelope that clients parse before streaming chunks
+    enc := json.NewEncoder(w)
+    return enc.Encode(ctrl)
 }
+
+// When a rate limit occurs before streaming starts, send a control frame with retry_after seconds
+func EmitRateLimitFrame(w io.Writer, retryAfter int) error {
+    ctrl := ControlMessage{
+        Type: "error",
+        Payload: map[string]interface{}{"error": map[string]interface{}{"type":"rate_limit","message":"rate limit exceeded","retry_after":retryAfter}},
+    }
+    return EmitControlFrame(w, ctrl)
+}
